  "elo_playedtimes" bigint NOT NULL DEFAULT '0' CHECK ("elo_playedtimes" BETWEEN 0 AND 4294967295),
  "card" bigint NOT NULL DEFAULT '0' CHECK ("card" BETWEEN 0 AND 4294967295),
  "cd_s" bigint NOT NULL DEFAULT '0' CHECK ("cd_s" BETWEEN 0 AND 4294967295),
  "cd_a" bigint NOT NULL DEFAULT '0' CHECK ("cd_a" BETWEEN 0 AND 4294967295),
  "cd_a1" bigint NOT NULL DEFAULT '0' CHECK ("cd_a1" BETWEEN 0 AND 4294967295),
