CREATE TABLE IF NOT EXISTS acfun_legacy.source_tables (
  source_name text PRIMARY KEY,source_engine text,source_columns integer,
  approximate_rows bigint,source_metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  captured_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS acfun_legacy.snapshot_runs (
  snapshot_id text PRIMARY KEY, source_label text NOT NULL,
  declared_table_count integer NOT NULL, state text NOT NULL DEFAULT 'staging',
  started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,notes text
);
CREATE TABLE IF NOT EXISTS acfun_legacy.snapshot_rows (
  snapshot_id text NOT NULL REFERENCES acfun_legacy.snapshot_runs(snapshot_id),
  source_table text NOT NULL,source_ordinal bigint NOT NULL,
  row_data jsonb NOT NULL,source_sha256 text NOT NULL
  CHECK (source_sha256 ~ '^[a-f0-9]{64}$'),
  PRIMARY KEY(snapshot_id,source_table,source_ordinal)
);
